iption\":\"The primary post content. It has a higher limit than post contents to allow storing a larger text that can later be refined into smaller posts.\"},\"labels\":{\"type\":\"union\",\"description\":\"Self-label values for this post. Effectively content warnings.\",\"refs\":[\"com.atproto.label.defs#selfLabels\"]},\"embedImages\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedImage\"},\"maxLength\":4},\"embedGallery\":{\"type\":\"ref\",\"ref\":\"#draftEmbedGallery\"},\"embedVideos\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedVideo\"},\"maxLength\":1},\"embedExternals\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedExternal\"},\"maxLength\":1},\"embedRecords\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedRecord\"},\"maxLength\":1}}},\"draftView\":{\"description\":\"View to present drafts data to users.\",\"type\":\"object\",\"required\":[\"id\",\"draft\",\"createdAt\",\"updatedAt\"],\"properties\":{\"id\":{\"description\":\"A TID to be used as a draft identifier.\",\"type\":\"string\",\"format\":\"tid\"},\"draft\":{\"type\":\"ref\",\"ref\":\"#draft\"},\"createdAt\":{\"description\":\"The time the draft was created.\",\"type\":\"string\",\"format\":\"datetime\"},\"updatedAt\":{\"description\":\"The time the draft was last updated.\",\"type\":\"string\",\"format\":\"datetime\"}}},\"draftEmbedLocalRef\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Local, on-device ref to file to be embedded. Embeds are currently device-bound for drafts.\",\"minLength\":1,\"maxLength\":1024}}},\"draftEmbedCaption\":{\"type\":\"object\",\"required\":[\"lang\",\"content\"],\"properties\":{\"lang\":{\"type\":\"string\",\"format\":\"language\"},\"content\":{\"type\":\"string\",\"maxLength\":10000}}},\"draftEmbedGallery\":{\"type\":\"object\",\"required\":[\"items\"],\"properties\":{\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedGalleryItems\"}}},\"draftEmbedGalleryItems\":{\"type\":\"array\",\"items\":{\"type\":\"union\",\"refs\":[\"#draftEmbedImage\"]},\"maxLength\":20,\"description\":\"The schema-level maxLength of 20 is a future-proof ceiling. Clients should currently enforce a soft limit of 10 items in authoring UIs.\"},\"draftEmbedImage\":{\"type\":\"object\",\"required\":[\"localRef\"],\"properties\":{\"localRef\":{\"type\":\"ref\",\"ref\":\"#draftEmbedLocalRef\"},\"alt\":{\"type\":\"string\",\"maxGraphemes\":2000}}},\"draftEmbedVideo\":{\"type\":\"object\",\"required\":[\"localRef\"],\"properties\":{\"localRef\":{\"type\":\"ref\",\"ref\":\"#draftEmbedLocalRef\"},\"alt\":{\"type\":\"string\",\"maxGraphemes\":2000},\"captions\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#draftEmbedCaption\"},\"maxLength\":20}}},\"draftEmbedExternal\":{\"type\":\"object\",\"required\":[\"uri\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"}}},\"draftEmbedRecord\":{\"type\":\"object\",\"required\":[\"record\"],\"properties\":{\"record\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}}}}}")
