        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.external\",\"defs\":{\"main\":{\"type\":\"object\",\"description\":\"A representation of some externally linked content (eg, a URL and 'card'), embedded in a Bluesky record (eg, a post).\",\"required\":[\"external\"],\"properties\":{\"external\":{\"type\":\"ref\",\"ref\":\"#external\"}}},\"external\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"thumb\":{\"type\":\"blob\",\"accept\":[\"image/*\"],\"maxSize\":1000000},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"},\"description\":\"StrongRefs (uri+cid) of the Atmosphere records that backed this view.\"}}},\"view\":{\"type\":\"object\",\"required\":[\"external\"],\"properties\":{\"external\":{\"type\":\"ref\",\"ref\":\"#viewExternal\"}}},\"viewExternal\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"thumb\":{\"type\":\"string\",\"format\":\"uri\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"When the external content was created, if available. Example: a publication date, for an article.\"},\"updatedAt\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"When the external content was updated, if available.\"},\"readingTime\":{\"type\":\"integer\",\"description\":\"Estimated reading time in minutes, if applicable and available.\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"source\":{\"type\":\"ref\",\"ref\":\"#viewExternalSource\"},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"},\"description\":\"StrongRefs (uri+cid) of the Atmosphere records that backed this view.\"},\"associatedProfiles\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"},\"description\":\"Profiles of the owners of the Atmosphere records that backed this view.\"}}},\"viewExternalSource\":{\"type\":\"object\",\"description\":\"The source of an external embed, such as a standard.site publication.\",\"required\":[\"uri\",\"title\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"URI of the source, if available. Example: the https:// URL of a site.standard.publication record.\"},\"icon\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where an icon representing the source can be fetched. For example, CDN location provided by the App View.\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"theme\":{\"type\":\"ref\",\"ref\":\"#viewExternalSourceTheme\"}}},\"viewExternalSourceTheme\":{\"type\":\"object\",\"description\":\"The theme colors of an external source, such as a site.standard.publication. These colors may be used when rendering an embed from that source.\",\"properties\":{\"backgroundRGB\":{\"type\":\"ref\",\"ref\":\"#colorRGB\"},\"foregroundRGB\":{\"type\":\"ref\",\"ref\":\"#colorRGB\"},\"accentRGB\":{\"type\":\"ref\",\"ref\":\"#colorRGB\"},\"accentForegroundRGB\":{\"type\":\"ref\",\"ref\":\"#colorRGB\"}}},\"colorRGB\":{\"type\":\"object\",\"description\":\"RGB color definition, inspired by site.standard.theme.color#rgb\",\"required\":[\"r\",\"g\",\"b\"],\"properties\":{\"r\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":255},\"g\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":255},\"b\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":255}}},\"viewArticle\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"updatedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}},\"associatedProfiles\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}},\"image\":{\"type\":\"string\",\"format\":\"uri\"},\"publisher\":{\"type\":\"ref\",\"ref\":\"#viewArticlePublication\"},\"readingTime\":{\"type\":\"integer\",\"minimum\":1},\"likeCount\":{\"type\":\"integer\",\"minimum\":0},\"likers\":{\"type\":\"array\",\"maxLength\":3,\"description\":\"Available profile previews. Selected deterministically by DID; not a ranking.\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}}}},\"viewArticlePublication\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"updatedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}},\"associatedProfiles\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}},\"logo\":{\"type\":\"string\",\"format\":\"uri\"},\"image\":{\"type\":\"string\",\"format\":\"uri\"},\"theme\":{\"type\":\"ref\",\"ref\":\"#viewArticlePublicationTheme\"},\"subscriptionCount\":{\"type\":\"integer\",\"minimum\":0},\"subscribers\":{\"type\":\"array\",\"maxLength\":3,\"description\":\"Available profile previews. Selected deterministically by DID; not a ranking.\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}}}},\"viewArticlePublicationTheme\":{\"type\":\"object\",\"properties\":{\"background\":{\"type\":\"string\",\"description\":\"Hex color string, if available. Example: '#ffffff'.\"},\"foreground\":{\"type\":\"string\",\"description\":\"Hex color string, if available. Example: '#ffffff'.\"},\"accent\":{\"type\":\"string\",\"description\":\"Hex color string, if available. Example: '#ffffff'.\"},\"accentForeground\":{\"type\":\"string\",\"description\":\"Hex color string, if available. Example: '#ffffff'.\"}}},\"viewGallery\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\",\"items\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"updatedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}},\"associatedProfiles\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}},\"items\":{\"type\":\"array\",\"items\":{\"type\":\"union\",\"refs\":[\"#viewGalleryImage\"]},\"description\":\"The media items in the gallery. Each item may be of a different type, but all types must be supported by the client.\"},\"likeCount\":{\"type\":\"integer\",\"minimum\":0},\"likers\":{\"type\":\"array\",\"maxLength\":3,\"description\":\"Available profile previews. Selected deterministically by DID; not a ranking.\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}}}},\"viewGalleryImage\":{\"type\":\"object\",\"required\":[\"thumbnail\",\"fullsize\"],\"properties\":{\"thumbnail\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a thumbnail of the image can be fetched. For example, CDN location provided by the App View.\"},\"fullsize\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a large version of the image can be fetched. May or may not be the exact original blob. For example, CDN location provided by the App View.\"},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the image, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"}}},\"viewLivestream\":{\"type\":\"object\",\"required\":[\"uri\",\"title\",\"description\",\"active\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"uri\"},\"title\":{\"type\":\"string\"},\"description\":{\"type\":\"string\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"updatedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}},\"associatedProfiles\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"}},\"image\":{\"type\":\"string\",\"format\":\"uri\"},\"active\":{\"type\":\"boolean\",\"description\":\"True if the livestream is currently active at the time this view is served, false if it has ended.\"},\"startedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"endedAt\":{\"type\":\"string\",\"format\":\"datetime\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.gallery\",\"description\":\"An assortment of media embedded in a Bluesky record (eg, a post).\",\"defs\":{\"main\":{\"type\":\"object\",\"required\":[\"items\"],\"properties\":{\"items\":{\"type\":\"array\",\"maxLength\":20,\"description\":\"The schema-level maxLength of 20 is a future-proof ceiling. Clients should currently enforce a soft limit of 10 items in authoring UIs.\",\"items\":{\"type\":\"union\",\"refs\":[\"#image\"],\"description\":\"The media items in the gallery. Each item may be of a different type, but all types must be supported by the client.\"}}}},\"image\":{\"type\":\"object\",\"required\":[\"image\",\"alt\",\"aspectRatio\"],\"properties\":{\"image\":{\"type\":\"blob\",\"accept\":[\"image/*\"],\"maxSize\":2000000},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the image, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"}}},\"view\":{\"type\":\"object\",\"required\":[\"items\"],\"properties\":{\"items\":{\"type\":\"array\",\"items\":{\"type\":\"union\",\"refs\":[\"#viewImage\"]}}}},\"viewImage\":{\"type\":\"object\",\"required\":[\"thumbnail\",\"fullsize\",\"alt\",\"aspectRatio\"],\"properties\":{\"thumbnail\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a thumbnail of the image can be fetched. For example, CDN location provided by the App View.\"},\"fullsize\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a large version of the image can be fetched. May or may not be the exact original blob. For example, CDN location provided by the App View.\"},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the image, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.getEmbedExternalView\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Resolve one AT-URI record into the data needed to render an enhanced external embed. The records are validated against the requested `url` before any view is built. When validation passes, returns `data`, `associatedRefs` (strongRefs to embed into a post's external.associatedRefs) and the raw `associatedRecords`, plus a legacy `view` for Standard.site records only. When validation fails, only `unverifiedAssociatedRefs` and `unverifiedAssociatedRecords` are returned and no view or data is built. The response is empty (`{}`) when no record URI was usable or the record could not be resolved; clients should fall back to their own link-card rendering in that case and skip writing strongRefs to the post.\",\"parameters\":{\"type\":\"params\",\"required\":[\"url\"],\"properties\":{\"url\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"The canonical web URL the embed represents (typically the URL the user pasted into the composer). Used as the returned view's `uri`, and validated against the resolved records.\"},\"canonicalUri\":{\"type\":\"string\",\"format\":\"at-uri\",\"description\":\"The canonical AT URI of the atproto record found on the webpage. When provided, takes precedence over `uris`, which is then ignored.\"},\"uris\":{\"type\":\"array\",\"description\":\"Legacy input for Standard.site callers, ignored when `canonicalUri` is provided. A single record is selected from it: the first site.standard.document URI, otherwise the first site.standard.publication URI. Other entries are ignored; a document's publication is discovered from the document itself.\",\"items\":{\"type\":\"string\",\"format\":\"at-uri\"},\"maxLength\":4}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"properties\":{\"view\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.external#view\",\"description\":\"Legacy hydrated view of the embed, returned for Standard.site records only. Present only when validation passed and the records supply enough information to populate the required `viewExternal` fields.\"},\"data\":{\"type\":\"union\",\"refs\":[\"app.bsky.embed.external#viewArticle\",\"app.bsky.embed.external#viewArticlePublication\",\"app.bsky.embed.external#viewGallery\",\"app.bsky.embed.external#viewLivestream\"],\"description\":\"Preferred to #view. Hydrated data of the embed. Present only when validation passed and the records supply enough information to populate the required fields.\"},\"associatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"},\"description\":\"StrongRefs (URI+CID) of the Atmosphere records selected for persistence in a post, suitable for embedding into its external.associatedRefs: the canonical record, plus only the additional records the service chooses to persist for its collection. This can be a subset of the records used to render `data`, which may also draw on other hydrated records such as recommendations, subscriptions, or favorites. Present only when validation passed. Index-aligned with `associatedRecords`.\"},\"associatedRecords\":{\"type\":\"array\",\"items\":{\"type\":\"unknown\",\"description\":\"The raw record data of the Atmosphere records selected for persistence, index-aligned with `associatedRefs`. Returned for convenience, to avoid the client separately fetching them. Present only when validation passed.\"}},\"unverifiedAssociatedRefs\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"},\"description\":\"StrongRefs (URI+CID) of the same persistence-selected Atmosphere records (the canonical record plus chosen additional records) when validation of the requested `url` failed. These must not be written to a post. Index-aligned with `unverifiedAssociatedRecords`.\"},\"unverifiedAssociatedRecords\":{\"type\":\"array\",\"items\":{\"type\":\"unknown\",\"description\":\"The raw record data of the persistence-selected Atmosphere records, index-aligned with `unverifiedAssociatedRefs`. Present only when validation failed.\"}}}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.images\",\"description\":\"A set of images embedded in a Bluesky record (eg, a post).\",\"defs\":{\"main\":{\"type\":\"object\",\"required\":[\"images\"],\"properties\":{\"images\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#image\"},\"maxLength\":4}}},\"image\":{\"type\":\"object\",\"required\":[\"image\",\"alt\"],\"properties\":{\"image\":{\"type\":\"blob\",\"description\":\"The raw image file. May be up to 2 MB, formerly limited to 1 MB.\",\"accept\":[\"image/*\"],\"maxSize\":2000000},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the image, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"}}},\"view\":{\"type\":\"object\",\"required\":[\"images\"],\"properties\":{\"images\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#viewImage\"},\"maxLength\":4}}},\"viewImage\":{\"type\":\"object\",\"required\":[\"thumb\",\"fullsize\",\"alt\"],\"properties\":{\"thumb\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a thumbnail of the image can be fetched. For example, CDN location provided by the App View.\"},\"fullsize\":{\"type\":\"string\",\"format\":\"uri\",\"description\":\"Fully-qualified URL where a large version of the image can be fetched. May or may not be the exact original blob. For example, CDN location provided by the App View.\"},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the image, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.record\",\"description\":\"A representation of a record embedded in a Bluesky record (eg, a post). For example, a quote-post, or sharing a feed generator record.\",\"defs\":{\"main\":{\"type\":\"object\",\"required\":[\"record\"],\"properties\":{\"record\":{\"type\":\"ref\",\"ref\":\"com.atproto.repo.strongRef\"}}},\"view\":{\"type\":\"object\",\"required\":[\"record\"],\"properties\":{\"record\":{\"type\":\"union\",\"refs\":[\"#viewRecord\",\"#viewNotFound\",\"#viewBlocked\",\"#viewDetached\",\"app.bsky.feed.defs#generatorView\",\"app.bsky.graph.defs#listView\",\"app.bsky.labeler.defs#labelerView\",\"app.bsky.graph.defs#starterPackViewBasic\"]}}},\"viewRecord\":{\"type\":\"object\",\"required\":[\"uri\",\"cid\",\"author\",\"value\",\"indexedAt\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"at-uri\"},\"cid\":{\"type\":\"string\",\"format\":\"cid\"},\"author\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"},\"value\":{\"type\":\"unknown\",\"description\":\"The record data itself.\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"replyCount\":{\"type\":\"integer\"},\"repostCount\":{\"type\":\"integer\"},\"likeCount\":{\"type\":\"integer\"},\"quoteCount\":{\"type\":\"integer\"},\"opThreadPostIndex\":{\"type\":\"integer\",\"description\":\"The 1-indexed position of this post within the contiguous OP thread. Only present when this post is part of the OP thread.\"},\"opThreadPostCount\":{\"type\":\"integer\",\"description\":\"The total number of posts in the contiguous OP thread that this post belongs to. Only present when this post is part of the OP thread.\"},\"embeds\":{\"type\":\"array\",\"items\":{\"type\":\"union\",\"refs\":[\"app.bsky.embed.images#view\",\"app.bsky.embed.video#view\",\"app.bsky.embed.gallery#view\",\"app.bsky.embed.external#view\",\"app.bsky.embed.record#view\",\"app.bsky.embed.recordWithMedia#view\"]}},\"indexedAt\":{\"type\":\"string\",\"format\":\"datetime\"}}},\"viewNotFound\":{\"type\":\"object\",\"required\":[\"uri\",\"notFound\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"at-uri\"},\"notFound\":{\"type\":\"boolean\",\"const\":true}}},\"viewBlocked\":{\"type\":\"object\",\"required\":[\"uri\",\"blocked\",\"author\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"at-uri\"},\"blocked\":{\"type\":\"boolean\",\"const\":true},\"author\":{\"type\":\"ref\",\"ref\":\"app.bsky.feed.defs#blockedAuthor\"}}},\"viewDetached\":{\"type\":\"object\",\"required\":[\"uri\",\"detached\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"at-uri\"},\"detached\":{\"type\":\"boolean\",\"const\":true}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.recordWithMedia\",\"description\":\"A representation of a record embedded in a Bluesky record (eg, a post), alongside other compatible embeds. For example, a quote post and image, or a quote post and external URL card.\",\"defs\":{\"main\":{\"type\":\"object\",\"required\":[\"record\",\"media\"],\"properties\":{\"record\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.record\"},\"media\":{\"type\":\"union\",\"refs\":[\"app.bsky.embed.images\",\"app.bsky.embed.video\",\"app.bsky.embed.gallery\",\"app.bsky.embed.external\"]}}},\"view\":{\"type\":\"object\",\"required\":[\"record\",\"media\"],\"properties\":{\"record\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.record#view\"},\"media\":{\"type\":\"union\",\"refs\":[\"app.bsky.embed.images#view\",\"app.bsky.embed.video#view\",\"app.bsky.embed.gallery#view\",\"app.bsky.embed.external#view\"]}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.embed.video\",\"description\":\"A video embedded in a Bluesky record (eg, a post).\",\"defs\":{\"main\":{\"type\":\"object\",\"required\":[\"video\"],\"properties\":{\"video\":{\"type\":\"blob\",\"description\":\"The mp4 video file. May be up to 300mb, formerly limited to 100mb.\",\"accept\":[\"video/mp4\"],\"maxSize\":300000000},\"captions\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#caption\"},\"maxLength\":20},\"alt\":{\"type\":\"string\",\"description\":\"Alt text description of the video, for accessibility.\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"},\"presentation\":{\"type\":\"string\",\"description\":\"A hint to the client about how to present the video.\",\"knownValues\":[\"default\",\"gif\"]}}},\"caption\":{\"type\":\"object\",\"required\":[\"lang\",\"file\"],\"properties\":{\"lang\":{\"type\":\"string\",\"format\":\"language\"},\"file\":{\"type\":\"blob\",\"accept\":[\"text/vtt\"],\"maxSize\":20000}}},\"view\":{\"type\":\"object\",\"required\":[\"cid\",\"playlist\"],\"properties\":{\"cid\":{\"type\":\"string\",\"format\":\"cid\"},\"playlist\":{\"type\":\"string\",\"format\":\"uri\"},\"thumbnail\":{\"type\":\"string\",\"format\":\"uri\"},\"alt\":{\"type\":\"string\"},\"aspectRatio\":{\"type\":\"ref\",\"ref\":\"app.bsky.embed.defs#aspectRatio\"},\"presentation\":{\"type\":\"string\",\"description\":\"A hint to the client about how to present the video.\",\"knownValues\":[\"default\",\"gif\"]}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.feed.defs\",\"defs\":{\"postView\":{\"type\":\"object\",\"required\":[\"uri\",\"cid\",\"author\",\"record\",\"indexedAt\"],\"properties\":{\"uri\":{\"type\":\"string\",\"format\":\"at-uri\"},\"cid\":{\"type\":\"string\",\"format\":\"cid\"},\"author\":{\"type\":\"ref\",\"ref\":\"app.bsky.actor.defs#profileViewBasic\"},\"record\":{\"type\":\"unknown\"},\"embed\":{\"type\":\"union\",\"refs\":[\"app.bsky.embed.images#view\",\"app.bsky.embed.video#view\",\"app.bsky.embed.gallery#view\",\"app.bsky.embed.external#view\",\"app.bsky.embed.record#view\",\"app.bsky.embed.recordWithMedia#view\"]},\"bookmarkCount\":{\"type\":\"integer\"},\"replyCount\":{\"type\":\"integer\"},\"repostCount\":{\"type\":\"integer\"},\"likeCount\":{\"type\":\"integer\"},\"quoteCount\":{\"type\":\"integer\"},\"indexedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"viewer\":{\"type\":\"ref\",\"ref\":\"#viewerState\"},\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}},\"threadgate\":{\"type\":\"ref\",\"ref\":\"#threadgateView\"},\"debug\":{\"type\":\"unknown\",\"description\":\"Debug information for internal development\"}}},\"viewerState\":{\"type\":\"object\",\"description\":\"Metadata about the requesting account's relationship with the subject content. Only has meaningful content for authed requests.\",\"properties\":{\"repost\":{\"type\":\"string\",\"format\":\"at-uri\"},\"like\":{\"type\":\"string\",\"format\":\"at-uri\"},\"bookmarked\":{\"type\":\"boolean\"},\"threadMuted\":{\"type\":\"boolean\"},\"replyDisabled\":{\"type\":\"boolean\"},\"embeddingDisabled\":{\"type\":\"boolean\"},\"pinned\":{\"type\":\"boolean\"},\"knownLikers\":{\"description\":\"This property is present only in selected cases, as an optimization.\",\"type\":\"ref\",\"ref\":\"#knownLikers\"}}},\"knownLikers\":{\"type\":\"object\",\"description\":\"The post's likers whom you also follow\",\"required\":[\"count\",\"