        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.video.getUploadStatus\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Get the authoritative status of the upload phase. Terminal states remain readable. completedJobId and jobStatus are present only for completed sessions; failureReason is present only for failed sessions.\",\"parameters\":{\"type\":\"params\",\"required\":[\"jobId\"],\"properties\":{\"jobId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"jobId\",\"partSizeBytes\",\"partCount\",\"receivedParts\",\"expiresAt\",\"state\"],\"properties\":{\"jobId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256},\"partSizeBytes\":{\"type\":\"integer\"},\"partCount\":{\"type\":\"integer\"},\"receivedParts\":{\"type\":\"array\",\"items\":{\"type\":\"integer\",\"minimum\":1}},\"expiresAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"state\":{\"type\":\"string\",\"maxLength\":32,\"knownValues\":[\"created\",\"finishing\",\"completed\",\"failed\",\"aborted\",\"expired\"]},\"completedJobId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256,\"description\":\"Present only when state is completed; may differ from jobId on deduplication.\"},\"jobStatus\":{\"type\":\"ref\",\"ref\":\"app.bsky.video.defs#jobStatus\",\"description\":\"Present only when state is completed.\"},\"failureReason\":{\"type\":\"string\",\"maxLength\":1024,\"description\":\"Present only when state is failed.\"}}}},\"errors\":[{\"name\":\"UploadNotFound\",\"description\":\"The job ID is unknown or aged out of retention; known terminal sessions remain readable and are never reported as not found.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"app.bsky.video.startUpload\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Start a multipart video upload. The declared size is exact, while optional media properties are advisory and used only for early failure; the authoritative probe runs asynchronously after upload.\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"sizeBytes\",\"mimeType\"],\"properties\":{\"sizeBytes\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"Exact byte size of the complete upload-ready video file before it is split into parts.\"},\"mimeType\":{\"type\":\"string\",\"minLength\":3,\"maxLength\":255,\"description\":\"Declared MIME type of the video.\"},\"name\":{\"type\":\"string\",\"maxLength\":256,\"description\":\"Optional client-provided file name.\"},\"durationMs\":{\"type\":\"integer\",\"description\":\"Advisory, non-authoritative duration used only for early failure; the authoritative probe runs asynchronously after upload.\"},\"width\":{\"type\":\"integer\",\"description\":\"Advisory, non-authoritative width used only for early failure; the authoritative probe runs asynchronously after upload.\"},\"height\":{\"type\":\"integer\",\"description\":\"Advisory, non-authoritative height used only for early failure; the authoritative probe runs asynchronously after upload.\"}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"jobId\",\"partSizeBytes\",\"partCount\",\"expiresAt\"],\"properties\":{\"jobId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":256},\"partSizeBytes\":{\"type\":\"integer\"},\"partCount\":{\"type\":\"integer\"},\"expiresAt\":{\"type\":\"string\",\"format\":\"datetime\"}}}},\"errors\":[{\"name\":\"UnsupportedContentType\",\"description\":\"The declared MIME type is not supported.\"},{\"name\":\"VideoTooLarge\",\"description\":\"The exact file size exceeds the per-file cap or remaining daily byte allowance