ef\":\"#convoStatus\"},\"unreadCount\":{\"type\":\"integer\"},\"kind\":{\"description\":\"Union field that has data specific to different kinds of convos.\",\"type\":\"union\",\"refs\":[\"#directConvo\",\"#groupConvo\"]}}},\"directConvo\":{\"type\":\"object\",\"properties\":{}},\"groupConvo\":{\"type\":\"object\",\"required\":[\"createdAt\",\"lockStatus\",\"lockStatusModerationOverride\",\"memberCount\",\"memberLimit\",\"name\"],\"properties\":{\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"joinLink\":{\"type\":\"ref\",\"ref\":\"chat.bsky.group.defs#joinLinkView\"},\"joinRequestCount\":{\"type\":\"integer\",\"description\":\"The total number of pending join requests for the group conversation. Only present for the owner. Capped at 21.\"},\"lockStatus\":{\"description\":\"The lock status of the conversation.\",\"type\":\"ref\",\"ref\":\"#convoLockStatus\"},\"lockStatusModerationOverride\":{\"description\":\"Whether the lock status is being forced by a moderation override (account inactivation or convo takedown) rather than the owner's own setting.\",\"type\":\"boolean\"},\"memberCount\":{\"type\":\"integer\",\"description\":\"The total number of members in the group conversation.\"},\"memberLimit\":{\"type\":\"integer\",\"description\":\"The maximum number of members allowed in the group conversation.\"},\"name\":{\"type\":\"string\",\"description\":\"The display name of the group conversation.\",\"maxGraphemes\":50,\"maxLength\":500},\"unreadJoinRequestCount\":{\"type\":\"integer\",\"description\":\"The number of unread join requests for the group conversation. Only present for the owner.\"}}},\"logBeginConvo\":{\"description\":\"Event indicating a convo containing the viewer was started. Can be direct or group. When a member is added to a group convo, they also get this event.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId\"],\"properties\":{\"rev\":{\"type\":\"string\"},\"convoId\":{\"type\":\"string\"}}},\"logAcceptConvo\":{\"description\":\