m message with data of type #systemMessageDataEditJoinLink\",\"type\":\"ref\",\"ref\":\"#systemMessageView\"}}},\"logEnableJoinLink\":{\"description\":\"Event indicating a join link was enabled for a group convo.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId\",\"message\"],\"properties\":{\"rev\":{\"type\":\"string\"},\"convoId\":{\"type\":\"string\"},\"message\":{\"description\":\"A system message with data of type #systemMessageDataEnableJoinLink\",\"type\":\"ref\",\"ref\":\"#systemMessageView\"}}},\"logDisableJoinLink\":{\"description\":\"Event indicating a join link was disabled for a group convo.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId\",\"message\"],\"properties\":{\"rev\":{\"type\":\"string\"},\"convoId\":{\"type\":\"string\"},\"message\":{\"description\":\"A system message with data of type #systemMessageDataDisableJoinLink\",\"type\":\"ref\",\"ref\":\"#systemMessageView\"}}},\"logIncomingJoinRequest\":{\"description\":\"Event indicating a join request was made to a group the viewer owns. Only the owner gets this.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId\",\"member\"],\"properties\":{\"rev\":{\"type\":\"string\"},\"convoId\":{\"type\":\"string\"},\"member\":{\"description\":\"Prospective member who requested to join.\",\"type\":\"ref\",\"ref\":\"chat.bsky.actor.defs#profileViewBasic\"}}},\"logApproveJoinRequest\":{\"description\":\"Event indicating a join request was approved by the viewer. Only the owner gets this. The approved member gets a logBeginConvo.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId\",\"member\"],\"properties\":{\"rev\":{\"type\":\"string\"},\"convoId\":{\"type\":\"string\"},\"member\":{\"description\":\"Prospective member who requested to join.\",\"type\":\"ref\",\"ref\":\"chat.bsky.actor.defs#profileViewBasic\"}}},\"logRejectJoinRequest\":{\"description\":\"Event indicating a join request was rejected by the viewer. Only the owner gets this.\",\"type\":\"object\",\"required\":[\"rev\",\"convoId