        documents.append("{\"lexicon\":1,\"id\":\"chat.bsky.group.approveJoinRequest\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Approves a request to join a group (via join link) the user owns. Action taken by the group owner.\",\"errors\":[{\"name\":\"InvalidConvo\"},{\"name\":\"InsufficientRole\"},{\"name\":\"MemberLimitReached\"}],\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"convoId\",\"member\"],\"properties\":{\"convoId\":{\"type\":\"string\"},\"member\":{\"type\":\"string\",\"format\":\"did\"}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"convo\"],\"properties\":{\"convo\":{\"type\":\"ref\",\"ref\":\"chat.bsky.convo.defs#convoView\"}}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"chat.bsky.group.createGroup\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Creates a group convo, specifying the members to be added to it. Unlike getConvoForMembers, this isn't idempotent. It will create new groups even if the membership is identical to pre-existing groups. Will create 'request' membership for all members, except the owner who is 'accepted'.\",\"errors\":[{\"name\":\"AccountSuspended\"},{\"name\":\"BlockedActor\"},{\"name\":\"BlockedSubject\"},{\"name\":\"NewAccountCannotCreateGroup\"},{\"name\":\"NotFollowedBySender\"},{\"name\":\"RecipientNotFound\"},{\"name\":\"UserForbidsGroups\"}],\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"members\",\"name\"],\"properties\":{\"members\":{\"type\":\"array\",\"description\":\"The members to add to the group. The owner is automatically added. Implementations may enforce a lower maximum than the 10,000-item schema limit; Bluesky currently supports up to 100 total members. If the owner is included in this list, the list may contain up to the implementation's total member limit. Otherwise, it may contain one fewer.\",\"maxLength\":10000,\"items\":{\"type\":\"string\",\"format\":\"did\"}},\"name\":{\"type\":\"string\",\"minLength\":1,\"maxGraphemes\":50,\"maxLength\":500}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"convo\"],\"properties\":{\"convo\":{\"type\":\"ref\",\"ref\":\"chat.bsky.convo.defs#convoView\"}}}}}}}")
