ted the convo.\",\"type\":\"integer\"},\"rev\":{\"type\":\"string\"},\"subjectDid\":{\"description\":\"The DID of the member who was added.\",\"type\":\"string\",\"format\":\"did\"},\"subjectFollowsOwner\":{\"description\":\"Whether the added member follows the group owner.\",\"type\":\"boolean\"}}},\"eventGroupChatMemberJoined\":{\"type\":\"object\",\"description\":\"Fired when a member joins a group chat via an join link that does not require approval.\",\"required\":[\"actorDid\",\"convoCreatedAt\",\"convoId\",\"createdAt\",\"groupMemberCount\",\"groupName\",\"joinLinkCode\",\"ownerDid\",\"rev\",\"subjectFollowsOwner\"],\"properties\":{\"actorDid\":{\"description\":\"The DID of the person joining.\",\"type\":\"string\",\"format\":\"did\"},\"convoCreatedAt\":{\"description\":\"When the group was originally created.\",\"type\":\"string\",\"format\":\"datetime\"},\"convoId\":{\"type\":\"string\"},\"createdAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"groupMemberCount\":{\"description\":\"Current member count at the time of the event.\",\"type\":\"integer\"},\"groupName\":{\"type\":\"string\"},\"joinLinkCode\":{\"description\":\"The code of the join link used to join.\",\"type\":\"string\"},\"ownerDid\":{\"description\":\"The DID of the group chat owner.\",\"type\":\"string\",\"format\":\"did\"},\"rev\":{\"type\":\"string\"},\"subjectFollowsOwner\":{\"description\":\"Whether the joining member follows the group owner.\",\"type\":\"boolean\"}}},\"eventGroupChatJoinRequest\":{\"type\":\"object\",\"description\":\"Fired when a user requests to join a group chat via an join link that requires approval.\",\"required\":[\"actorDid\",\"convoCreatedAt\",\"convoId\",\"createdAt\",\"groupMemberCount\",\"groupName\",\"joinLinkCode\",\"ownerDid\",\"rev\",\"subjectFollowsOwner\"],\"properties\":{\"actorDid\":{\"description\":\"The DID of the person requesting to join.\",\"type\":\"string\",\"format\":\"did\"},\"convoCreatedAt\":{\"description\":\"When the group was origina