        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.sync.notifyOfUpdate\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Notify a crawling service of a recent update, and that crawling should resume. Intended use is after a gap between repo stream events caused the crawling service to disconnect. Does not require auth; implemented by Relay. DEPRECATED: just use com.atproto.sync.requestCrawl\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"hostname\"],\"properties\":{\"hostname\":{\"type\":\"string\",\"description\":\"Hostname of the current service (usually a PDS) that is notifying of update.\"}}}}}}}")
