        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.sync.subscribeRepos\",\"defs\":{\"main\":{\"type\":\"subscription\",\"description\":\"Repository event stream, aka Firehose endpoint. Outputs repo commits with diff data, and identity update events, for all repositories on the current server. See the atproto specifications for details around stream sequencing, repo versioning, CAR diff format, and more. Public and does not require auth; implemented by PDS and Relay.\",\"parameters\":{\"type\":\"params\",\"properties\":{\"cursor\":{\"type\":\"integer\",\"description\":\"The last known event seq number to backfill from.\"}}},\"message\":{\"schema\":{\"type\":\"union\",\"refs\":[\"#commit\",\"#sync\",\"#identity\",\"#account\",\"#info\"]}},\"errors\":[{\"name\":\"FutureCursor\"},{\"name\":\"ConsumerTooSlow\",\"description\":\"If the consumer of the stream can not keep up with events, and a backlog gets too large, the server will drop the connection.\"}]},\"commit\":{\"type\":\"object\",\"description\":\"Represents an update of repository state. Note that empty commits are allowed, which include no repo data changes, but an update to rev and signature.\",\"required\":[\"seq\",\"rebase\",\"tooBig\",\"repo\",\"commit\",\"rev\",\"since\",\"blocks\",\"ops\",\"blobs\",\"time\"],\"nullable\":[\"since\"],\"properties\":{\"seq\":{\"type\":\"integer\",\"description\":\"The stream sequence number of this message.\"},\"rebase\":{\"type\":\"boolean\",\"description\":\"DEPRECATED -- unused\"},\"tooBig\":{\"type\":\"boolean\",\"description\":\"DEPRECATED -- replaced by #sync event and data limits. Indicates that this commit contained too many ops, or data size was too large. Consumers will need to make a separate request to get missing data.\"},\"repo\":{\"type\":\"string\",\"format\":\"did\",\"description\":\"The repo this event comes from. Note that all other message types name this field 'did'.\"},\"commit\":{\"type\":\"cid-link\",\"description\":\"Repo commit object CID.\"},\"rev\":{\"type\":\"string\",\"format\":\"tid\",\"description\":\"The rev of the emitted commit. Note that this information is also in the commit object included in blocks, unless this is a tooBig event.\"},\"since\":{\"type\":\"string\",\"format\":\"tid\",\"description\":\"The rev of the last emitted commit from this repo (if any).\"},\"blocks\":{\"type\":\"bytes\",\"description\":\"CAR file containing relevant blocks, as a diff since the previous repo state. The commit must be included as a block, and the commit block CID must be the first entry in the CAR header 'roots' list.\",\"maxLength\":2000000},\"ops\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#repoOp\",\"description\":\"List of repo mutation operations in this commit (eg, records created, updated, or deleted).\"},\"maxLength\":200},\"blobs\":{\"type\":\"array\",\"items\":{\"type\":\"cid-link\",\"description\":\"DEPRECATED -- will soon always be empty. List of new blobs (by CID) referenced by records in this commit.\"}},\"prevData\":{\"type\":\"cid-link\",\"description\":\"The root CID of the MST tree for the previous commit from this repo (indicated by the 'since' revision field in this message). Corresponds to the 'data' field in the repo commit object. NOTE: this field is effectively required for the 'inductive' version of firehose.\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"Timestamp of when this message was originally broadcast.\"}}},\"sync\":{\"type\":\"object\",\"description\":\"Updates the repo to a new state, without necessarily including that state on the firehose. Used to recover from broken commit streams, data loss incidents, or in situations where upstream host does not know recent state of the repository.\",\"required\":[\"seq\",\"did\",\"blocks\",\"rev\",\"time\"],\"properties\":{\"seq\":{\"type\":\"integer\",\"description\":\"The stream sequence number of this message.\"},\"did\":{\"type\":\"string\",\"format\":\"did\",\"description\":\"The account this repo event corresponds to. Must match that in the commit object.\"},\"blocks\":{\"type\":\"bytes\",\"description\":\"CAR file containing the commit, as a block. The CAR header must include the commit block CID as the first 'root'.\",\"maxLength\":10000},\"rev\":{\"type\":\"string\",\"description\":\"The rev of the commit. This value must match that in the commit object.\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"Timestamp of when this message was originally broadcast.\"}}},\"identity\":{\"type\":\"object\",\"description\":\"Represents a change to an account's identity. Could be an updated handle, signing key, or pds hosting endpoint. Serves as a prod to all downstream services to refresh their identity cache.\",\"required\":[\"seq\",\"did\",\"time\"],\"properties\":{\"seq\":{\"type\":\"integer\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\"},\"handle\":{\"type\":\"string\",\"format\":\"handle\",\"description\":\"The current handle for the account, or 'handle.invalid' if validation fails. This field is optional, might have been validated or passed-through from an upstream source. Semantics and behaviors for PDS vs Relay may evolve in the future; see atproto specs for more details.\"}}},\"account\":{\"type\":\"object\",\"description\":\"Represents a change to an account's status on a host (eg, PDS or Relay). The semantics of this event are that the status is at the host which emitted the event, not necessarily that at the currently active PDS. Eg, a Relay takedown would emit a takedown with active=false, even if the PDS is still active.\",\"required\":[\"seq\",\"did\",\"time\",\"active\"],\"properties\":{\"seq\":{\"type\":\"integer\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\"},\"active\":{\"type\":\"boolean\",\"description\":\"Indicates that the account has a repository which can be fetched from the host that emitted this event.\"},\"status\":{\"type\":\"string\",\"description\":\"If active=false, this optional field indicates a reason for why the account is not active.\",\"knownValues\":[\"takendown\",\"suspended\",\"deleted\",\"deactivated\",\"desynchronized\",\"throttled\"]}}},\"info\":{\"type\":\"object\",\"required\":[\"name\"],\"properties\":{\"name\":{\"type\":\"string\",\"knownValues\":[\"OutdatedCursor\"]},\"message\":{\"type\":\"string\"}}},\"repoOp\":{\"type\":\"object\",\"description\":\"A repo operation, ie a mutation of a single record.\",\"required\":[\"action\",\"path\",\"cid\"],\"nullable\":[\"cid\"],\"properties\":{\"action\":{\"type\":\"string\",\"knownValues\":[\"create\",\"update\",\"delete\"]},\"path\":{\"type\":\"string\"},\"cid\":{\"type\":\"cid-link\",\"description\":\"For creates and updates, the new record CID. For deletions, null.\"},\"prev\":{\"type\":\"cid-link\",\"description\":\"For updates and deletes, the previous record CID (required for inductive firehose). For creations, field should not be defined.\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.addReservedHandle\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Add a handle to the set of reserved handles.\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"handle\"],\"properties\":{\"handle\":{\"type\":\"string\"}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"properties\":{}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.checkHandleAvailability\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Checks whether the provided handle is available. If the handle is not available, available suggestions will be returned. Optional inputs will be used to generate suggestions.\",\"parameters\":{\"type\":\"params\",\"required\":[\"handle\"],\"properties\":{\"handle\":{\"type\":\"string\",\"format\":\"handle\",\"description\":\"Tentative handle. Will be checked for availability or used to build handle suggestions.\"},\"email\":{\"type\":\"string\",\"description\":\"User-provided email. Might be used to build handle suggestions.\"},\"birthDate\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"User-provided birth date. Might be used to build handle suggestions.\"}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"handle\",\"result\"],\"properties\":{\"handle\":{\"type\":\"string\",\"format\":\"handle\",\"description\":\"Echo of the input handle.\"},\"result\":{\"type\":\"union\",\"refs\":[\"#resultAvailable\",\"#resultUnavailable\"]}}}},\"errors\":[{\"name\":\"InvalidEmail\",\"description\":\"An invalid email was provided.\"}]},\"resultAvailable\":{\"type\":\"object\",\"description\":\"Indicates the provided handle is available.\",\"properties\":{}},\"resultUnavailable\":{\"type\":\"object\",\"description\":\"Indicates the provided handle is unavailable and gives suggestions of available handles.\",\"required\":[\"suggestions\"],\"properties\":{\"suggestions\":{\"type\":\"array\",\"description\":\"List of suggested handles based on the provided inputs.\",\"items\":{\"type\":\"ref\",\"ref\":\"#suggestion\"}}}},\"suggestion\":{\"type\":\"object\",\"required\":[\"handle\",\"method\"],\"properties\":{\"handle\":{\"type\":\"string\",\"format\":\"handle\"},\"method\":{\"type\":\"string\",\"description\":\"Method used to build this suggestion. Should be considered opaque to clients. Can be used for metrics.\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.checkSignupQueue\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Check accounts location in signup queue.\",\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"activated\"],\"properties\":{\"activated\":{\"type\":\"boolean\"},\"placeInQueue\":{\"type\":\"integer\"},\"estimatedTimeMs\":{\"type\":\"integer\"}}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.dereferenceScope\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Allows finding the oauth permission scope from a reference\",\"parameters\":{\"type\":\"params\",\"required\":[\"scope\"],\"properties\":{\"scope\":{\"type\":\"string\",\"description\":\"The scope reference (starts with 'ref:')\"}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"scope\"],\"properties\":{\"scope\":{\"type\":\"string\",\"description\":\"The full oauth permission scope\"}}}},\"errors\":[{\"name\":\"InvalidScopeReference\",\"description\":\"An invalid scope reference was provided.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.fetchLabels\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"DEPRECATED: use queryLabels or subscribeLabels instead -- Fetch all labels from a labeler created after a certain date.\",\"parameters\":{\"type\":\"params\",\"properties\":{\"since\":{\"type\":\"integer\"},\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":250,\"default\":50}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"labels\"],\"properties\":{\"labels\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"com.atproto.label.defs#label\"}}}}}}}}")
    }

    private static func appendChunk18(to documents: inout [String]) {
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.requestPhoneVerification\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Request a verification code to be sent to the supplied phone number\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"phoneNumber\"],\"properties\":{\"phoneNumber\":{\"type\":\"string\"}}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.atproto.temp.revokeAccountCredentials\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Revoke sessions, password, and app passwords associated with account. May be resolved by a password reset.\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"account\"],\"properties\":{\"account\":{\"type\":\"string\",\"format\":\"at-identifier\"}}}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"com.germnetwork.declaration\",\"defs\":{\"main\":{\"type\":\"record\",\"description\":\"A declaration of a Germ Network account\",\"key\":\"literal:self\",\"record\":{\"type\":\"object\",\"required\":[\"version\",\"currentKey\"],\"properties\":{\"version\":{\"type\":\"string\",\"description\":\"Semver version number, without pre-release or build information, for the format of opaque content\",\"minLength\":5,\"maxLength\":14},\"currentKey\":{\"type\":\"bytes\",\"description\":\"Opaque value, an ed25519 public key prefixed with a byte enum\"},\"messageMe\":{\"type\":\"ref\",\"description\":\"Controls who can message this account\",\"ref\":\"#messageMe\"},\"keyPackage\":{\"type\":\"bytes\",\"description\":\"Opaque value, contains MLS KeyPackage(s), and other signature data, and is signed by the currentKey\"},\"continuityProofs\":{\"type\":\"array\",\"description\":\"Array of opaque values to allow for key rolling\",\"items\":{\"type\":\"bytes\"},\"maxLength\":1000}}}},\"messageMe\":{\"type\":\"object\",\"required\":[\"showButtonTo\",\"messageMeUrl\"],\"properties\":{\"messageMeUrl\":{\"type\":\"string\",\"description\":\"A URL to present to an account that does not have its own com.germnetwork.declaration record, must have an empty fragment component, where the app should fill in the fragment component with the DIDs of the two accounts who wish to message each other\",\"format\":\"uri\",\"minLength\":1,\"maxLength\":2047},\"showButtonTo\":{\"type\":\"string\",\"knownValues\":[\"none\",\"usersIFollow\",\"everyone\"],\"description\":\"The policy of who can message the account, this value is included in the keyPackage, but is duplicated here to allow applications to decide if they should show a 'Message on Germ' button to the viewer.\",\"minLength\":1,\"maxLength\":100}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.getBlock\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Download a single block within a sealed segment file by index. Returns the raw zstd-compressed block frame exactly as stored on disk.\",\"parameters\":{\"type\":\"params\",\"required\":[\"segment\",\"blockIndex\"],\"properties\":{\"segment\":{\"type\":\"string\",\"description\":\"The sealed segment filename, e.g. seg_000000002a.jss.\"},\"blockIndex\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Zero-based block index within the segment. Must be < the segment's block_count.\"}}},\"output\":{\"encoding\":\"application/octet-stream\"},\"errors\":[{\"name\":\"SegmentNotFound\",\"description\":\"No sealed segment exists for the given name.\"},{\"name\":\"BlockNotFound\",\"description\":\"blockIndex is >= the segment's block_count.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.getImportStatus\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Report the status of a timestamp-import job: lifecycle state, current phase, per-phase progress, and (on completion) the parse/mutation totals. With no job parameter, reports the current or most recent job. Bearer-token gated: without a configured token the endpoint always returns 401.\",\"parameters\":{\"type\":\"params\",\"properties\":{\"job\":{\"type\":\"string\",\"description\":\"Job id returned by importTimestamps. When omitted, the current or most recent job is reported.\"}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"job\",\"state\"],\"properties\":{\"job\":{\"type\":\"string\",\"description\":\"Job id.\"},\"state\":{\"type\":\"string\",\"knownValues\":[\"running\",\"complete\",\"failed\"],\"description\":\"Lifecycle state.\"},\"phase\":{\"type\":\"string\",\"knownValues\":[\"parse_bucket\",\"apply\"],\"description\":\"Current phase: parse_bucket (Phase A+B) or apply (Phase C).\"},\"error\":{\"type\":\"string\",\"description\":\"Failure detail; present only when state is failed.\"},\"submittedAt\":{\"type\":\"string\",\"format\":\"datetime\"},\"finishedAt\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"Present only for a terminal job.\"},\"bucketed\":{\"type\":\"boolean\",\"description\":\"Whether Phase A+B completed (the offset files are durable).\"},\"segmentsToApply\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Segments Phase C will process (after resume-skips).\"},\"segmentsApplied\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Segments processed so far in Phase C.\"},\"rowsTotal\":{\"type\":\"integer\",\"minimum\":0},\"rowsValid\":{\"type\":\"integer\",\"minimum\":0},\"rowsRejected\":{\"type\":\"integer\",\"minimum\":0},\"segmentsExamined\":{\"type\":\"integer\",\"minimum\":0},\"segmentsPatched\":{\"type\":\"integer\",\"minimum\":0},\"rowsMutated\":{\"type\":\"integer\",\"minimum\":0},\"rowsMatchedAllVersions\":{\"type\":\"integer\",\"minimum\":0},\"rowsMatchedSpecific\":{\"type\":\"integer\",\"minimum\":0},\"specificCidsUnmatched\":{\"type\":\"integer\",\"minimum\":0},\"rowsCorruptOffset\":{\"type\":\"integer\",\"minimum\":0}}}},\"errors\":[{\"name\":\"JobNotFound\",\"description\":\"No import job matches the supplied id, or no job has ever run when the id is omitted.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.getSegment\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Download a sealed segment file by name.\",\"parameters\":{\"type\":\"params\",\"required\":[\"name\"],\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"The segment filename, e.g. seg_000000002a.jss\"}}},\"output\":{\"encoding\":\"application/octet-stream\"},\"errors\":[{\"name\":\"SegmentNotFound\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.getZstdDictionary\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Download the zstd dictionary used by the network.bsky.jetstream.subscribeEvents stream's optional compression scheme. The dictionary is requested by its zstd dictionary ID (the same ID embedded in every compressed frame's header); a client that wants compressed frames first fetches the server's current dictionary, then opts in on the websocket with zstdDictionary=<id>. The response is a raw zstd structured dictionary (RFC 8878 section 5), immutable for a given ID and CDN-cacheable. Servers may retire old dictionaries after retraining; a client holding a retired ID re-fetches without an id parameter to obtain the current one.\",\"parameters\":{\"type\":\"params\",\"properties\":{\"id\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"The zstd dictionary ID to fetch. Omitted: the server's current dictionary.\"}}},\"output\":{\"encoding\":\"application/octet-stream\"},\"errors\":[{\"name\":\"DictionaryNotFound\",\"description\":\"No dictionary with the given ID is available on this server.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.importTimestamps\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Submit a timestamp-import job. The referenced CSV is staged server-local out-of-band and named by a path confined to the server's configured import directory (paths escaping it via .. or a symlink are rejected). The job runs asynchronously and shares the segment-rewrite lock with delete-compaction, so only one import runs at a time; a concurrent submit is rejected. Bearer-token gated: without a configured token the endpoint always returns 401.\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"path\"],\"properties\":{\"path\":{\"type\":\"string\",\"description\":\"Server-local path to the plain (uncompressed) import CSV, resolved within the configured import directory. May be relative to that directory or an absolute path inside it.\"}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"job\"],\"properties\":{\"job\":{\"type\":\"string\",\"description\":\"Opaque job id. Poll getImportStatus with this id to observe progress and the terminal result.\"}}}},\"errors\":[{\"name\":\"ImportInProgress\",\"description\":\"Another import job is already running; only one runs at a time.\"},{\"name\":\"ImportNotReady\",\"description\":\"Timestamp import requires the server to be in steady state with the live writer running.\"},{\"name\":\"InvalidPath\",\"description\":\"The path is empty, escapes the import directory, does not exist, or is not a regular file.\"}]}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.listSegments\",\"defs\":{\"main\":{\"type\":\"query\",\"description\":\"Enumerate sealed segment files available for download, in ascending index order.\",\"parameters\":{\"type\":\"params\",\"properties\":{\"limit\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":1000,\"default\":100,\"description\":\"Maximum number of segment file names to return.\"},\"cursor\":{\"type\":\"string\",\"description\":\"Opaque pagination cursor from a previous response.\"}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"segments\"],\"properties\":{\"cursor\":{\"type\":\"string\"},\"segments\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#segment\"}}}}}},\"segment\":{\"type\":\"object\",\"required\":[\"name\",\"index\",\"sizeBytes\",\"checksum\",\"eventCount\",\"minSeq\",\"maxSeq\",\"minWitnessedAt\",\"maxWitnessedAt\"],\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"Segment filename; pass to getSegment.\"},\"index\":{\"type\":\"integer\",\"description\":\"Zero-based segment index.\"},\"sizeBytes\":{\"type\":\"integer\",\"description\":\"File size in bytes.\"},\"checksum\":{\"type\":\"string\",\"description\":\"Segment-format xxh3 metadata checksum as 16-char hex; equals the getSegment ETag.\"},\"eventCount\":{\"type\":\"integer\",\"description\":\"Number of events in the segment.\"},\"minSeq\":{\"type\":\"integer\"},\"maxSeq\":{\"type\":\"integer\"},\"minWitnessedAt\":{\"type\":\"integer\",\"description\":\"Earliest witnessed-at, unix microseconds.\"},\"maxWitnessedAt\":{\"type\":\"integer\",\"description\":\"Latest witnessed-at, unix microseconds.\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.planSnapshot\",\"defs\":{\"main\":{\"type\":\"procedure\",\"description\":\"Build a download plan for the desired data pattern. The plan lists whole segments or block ranges that might contain events for the requested kinds, DIDs, and collections.\",\"input\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"properties\":{\"kinds\":{\"type\":\"array\",\"maxLength\":4,\"description\":\"Event kinds to include. Omit this field or pass an empty array to include all kinds.\",\"items\":{\"type\":\"string\",\"enum\":[\"commit\",\"identity\",\"account\",\"sync\"]}},\"dids\":{\"type\":\"array\",\"maxLength\":10000,\"description\":\"Only include data for these DIDs. Omit this field or pass an empty array to include all DIDs.\",\"items\":{\"type\":\"string\",\"format\":\"did\"}},\"collections\":{\"type\":\"array\",\"maxLength\":100,\"description\":\"Collection NSIDs or namespace wildcards such as app.bsky.feed.*; constrains commit events only. Non-commit kinds are unaffected, so combine with kinds=commit for a commits-only collection plan. Rejected when kinds is set and excludes commit. Omit or pass an empty array to include all collections.\",\"items\":{\"type\":\"string\"}},\"afterSeq\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Start after this sequence number. Events at or below it are not included.\"},\"beforeSeq\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Stop at this sequence number. Events above it are not included.\"}}}},\"output\":{\"encoding\":\"application/json\",\"schema\":{\"type\":\"object\",\"required\":[\"plannedThroughSeq\",\"sealedTipSeq\",\"segments\",\"stats\"],\"properties\":{\"plannedThroughSeq\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"The last sealed sequence covered by this page. Use this value as afterSeq for the next page. If the response hits the server's page limit, this is the maxSeq of the last item returned; otherwise it equals sealedTipSeq. Planning is complete when plannedThroughSeq reaches sealedTipSeq.\"},\"sealedTipSeq\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"The end of the sealed archive for this snapshot, capped by beforeSeq when provided. Use this value as beforeSeq on later pages so the snapshot does not move while it is being downloaded.\"},\"segments\":{\"type\":\"array\",\"items\":{\"type\":\"ref\",\"ref\":\"#segment\"}},\"stats\":{\"type\":\"ref\",\"ref\":\"#stats\"}}}}},\"segment\":{\"type\":\"object\",\"required\":[\"name\",\"index\",\"checksum\",\"minSeq\",\"maxSeq\",\"mode\"],\"properties\":{\"name\":{\"type\":\"string\",\"description\":\"Segment filename to pass to getSegment or getBlock.\"},\"index\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Zero-based segment index.\"},\"checksum\":{\"type\":\"string\",\"minLength\":16,\"maxLength\":16,\"description\":\"The segment's xxh3 metadata checksum, encoded as 16 hexadecimal characters.\"},\"minSeq\":{\"type\":\"integer\",\"minimum\":0},\"maxSeq\":{\"type\":\"integer\",\"minimum\":0},\"mode\":{\"type\":\"string\",\"knownValues\":[\"segment\",\"blocks\"],\"description\":\"How to download this segment. For segment, download the whole file with getSegment. For blocks, download the ranges listed in blocks with getBlock.\"},\"blocks\":{\"type\":\"array\",\"description\":\"Block ranges to download, including both endpoints. This field is present only when mode is blocks.\",\"items\":{\"type\":\"ref\",\"ref\":\"#blockRange\"}}}},\"blockRange\":{\"type\":\"object\",\"required\":[\"first\",\"last\"],\"properties\":{\"first\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Index of the first block in the range.\"},\"last\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Index of the last block in the range.\"}}},\"stats\":{\"type\":\"object\",\"required\":[\"segmentsExamined\",\"segmentsMatched\",\"blocksMatched\",\"entries\"],\"properties\":{\"segmentsExamined\":{\"type\":\"integer\",\"minimum\":0},\"segmentsMatched\":{\"type\":\"integer\",\"minimum\":0},\"blocksMatched\":{\"type\":\"integer\",\"minimum\":0},\"entries\":{\"type\":\"integer\",\"minimum\":0,\"description\":\"Number of items counted toward the server's per-page plan limit.\"}}}}}")
        documents.append("{\"lexicon\":1,\"id\":\"network.bsky.jetstream.subscribeEvents\",\"defs\":{\"main\":{\"type\":\"subscription\",\"description\":\"Stream every archived and live Jetstream event in seq order, framed per the xrpc.v1.json subprotocol. The kinds, dids, and collections filters are independent predicates ANDed together; each is match-all when omitted. See the parameter and error descriptions for cursor, filtering, and compression semantics.\",\"subprotocol\":\"xrpc.v1.json\",\"parameters\":{\"type\":\"params\",\"properties\":{\"cursor\":{\"type\":\"integer\",\"description\":\"Resume position, inclusive: the server replays events with seq >= cursor and the client dedups the overlap. Values >= 1e15 are interpreted as a unix-microseconds timestamp instead of a seq and translated to the first seq witnessed at or after that instant; a timestamp below the retention floor clamps up to the floor and an #info OutdatedCursor frame is sent. Omitted: start at the live tip.\"},\"kinds\":{\"type\":\"array\",\"maxLength\":4,\"items\":{\"type\":\"string\",\"enum\":[\"commit\",\"identity\",\"account\",\"sync\"]},\"description\":\"Event kinds to receive; values are the message $type fragment names. Omitted or empty: all kinds. A value outside the enum is rejected pre-upgrade with HTTP 400 (InvalidRequest) rather than silently never matching.\"},\"dids\":{\"type\":\"array\",\"items\":{\"type\":\"string\",\"format\":\"did\"},\"maxLength\":10000,\"description\":\"Repo DIDs to receive events for; applies to every event kind. Omitted or empty: all repos.\"},\"collections\":{\"type\":\"array\",\"items\":{\"type\":\"string\"},\"maxLength\":100,\"description\":\"Collection NSIDs or '<prefix>.*' patterns; constrains which commit events are delivered. Non-commit kinds are unaffected — combine with kinds=commit for a commits-only collection stream. Rejected pre-upgrade with HTTP 400 (InvalidRequest) when kinds is set and excludes commit, since the filter could never apply. Omitted or empty: all collections.\"},\"maxMessageSizeBytes\":{\"type\":\"integer\",\"minimum\":0,\"maximum\":4294967295,\"default\":0,\"description\":\"Skip events whose uncompressed frame (envelope included) exceeds this many bytes. 0 (default) means no limit.\"},\"zstdDictionary\":{\"type\":\"integer\",\"minimum\":1,\"description\":\"Jetstream extension: opt into dict-zstd frame compression with the given zstd dictionary ID (obtained via network.bsky.jetstream.getZstdDictionary). Frames then arrive as binary websocket messages, each one zstd frame whose decompressed bytes are exactly the xrpc.v1.json text frame. An unknown or retired ID is rejected pre-upgrade with HTTP 400 carrying the current ID.\"}}},\"message\":{\"schema\":{\"type\":\"union\",\"refs\":[\"#commit\",\"#identity\",\"#account\",\"#sync\",\"#info\"]}},\"errors\":[{\"name\":\"ConsumerTooSlow\",\"description\":\"The client is far behind the live tip AND reading below the server's floor rate for a sustained window; the server drops adversarially-slow readers. A merely-slow-but-progressing reader is never dropped.\"},{\"name\":\"CursorTooOld\",\"description\":\"Rejected pre-upgrade with HTTP 400, never as a stream error frame: the requested seq cursor is below the server's retention floor. The message carries the floor seq; archive-backfilling clients re-enter backfill from their last durable seq.\"},{\"name\":\"UnknownZstdDictionary\",\"description\":\"Rejected pre-upgrade with HTTP 400, never as a stream error frame: the zstdDictionary ID is unknown or retired. The message carries the current dictionary ID; re-fetch via network.bsky.jetstream.getZstdDictionary.\"}]},\"commit\":{\"type\":\"object\",\"description\":\"A single record mutation (create, update, or delete).\",\"required\":[\"seq\",\"did\",\"time\",\"rev\",\"operation\",\"collection\",\"rkey\"],\"properties\":{\"seq\":{\"type\":\"integer\",\"description\":\"Jetstream's monotonic per-event sequence number; the stream cursor.\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"The event's display timestamp, microsecond precision: when Jetstream witnessed the event, unless an operator timestamp import overrode it. Timestamp cursors translate against the witnessed time, so after an import this value may not be a faithful resume position.\"},\"rev\":{\"type\":\"string\",\"format\":\"tid\",\"description\":\"The repo rev of the commit that produced this op.\"},\"operation\":{\"type\":\"string\",\"knownValues\":[\"create\",\"update\",\"delete\"]},\"collection\":{\"type\":\"string\",\"format\":\"nsid\",\"description\":\"Collection NSID of the record.\"},\"rkey\":{\"type\":\"string\",\"format\":\"record-key\",\"description\":\"Record key.\"},\"record\":{\"type\":\"unknown\",\"description\":\"The record decoded to JSON. Absent for deletes.\"},\"cid\":{\"type\":\"string\",\"format\":\"cid\",\"description\":\"CID of the record. Absent for deletes.\"}}},\"identity\":{\"type\":\"object\",\"description\":\"An identity change (handle or DID document update), wrapping the upstream firehose event verbatim.\",\"required\":[\"seq\",\"did\",\"time\",\"identity\"],\"properties\":{\"seq\":{\"type\":\"integer\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"The time Jetstream witnessed this event, microsecond precision. Timestamp imports apply only to record (commit) events, so this is always the witnessed time.\"},\"identity\":{\"type\":\"ref\",\"ref\":\"com.atproto.sync.subscribeRepos#identity\",\"description\":\"The upstream event; its seq and time are the upstream relay's, not Jetstream's.\"}}},\"account\":{\"type\":\"object\",\"description\":\"An account status change (active/deactivated/deleted/...), wrapping the upstream firehose event verbatim.\",\"required\":[\"seq\",\"did\",\"time\",\"account\"],\"properties\":{\"seq\":{\"type\":\"integer\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"The time Jetstream witnessed this event, microsecond precision. Timestamp imports apply only to record (commit) events, so this is always the witnessed time.\"},\"account\":{\"type\":\"ref\",\"ref\":\"com.atproto.sync.subscribeRepos#account\",\"description\":\"The upstream event; its seq and time are the upstream relay's, not Jetstream's.\"}}},\"sync\":{\"type\":\"object\",\"description\":\"An archived #sync event (broken commit chain; consumers should resync the repo), wrapping the upstream firehose event verbatim. Never emitted on the legacy v1 /subscribe wire.\",\"required\":[\"seq\",\"did\",\"time\",\"sync\"],\"properties\":{\"seq\":{\"type\":\"integer\"},\"did\":{\"type\":\"string\",\"format\":\"did\"},\"time\":{\"type\":\"string\",\"format\":\"datetime\",\"description\":\"The time Jetstream witnessed this event, microsecond precision. Timestamp imports apply only to record (commit) events, so this is always the witnessed time.\"},\"sync\":{\"type\":\"ref\",\"ref\":\"com.atproto.sync.subscribeRepos#sync\",\"description\":\"The upstream event; its seq and time are the upstream relay's, not Jetstream's.\"}}},\"info\":{\"type\":\"object\",\"description\":\"An advisory, non-fatal notice about the stream (mirrors com.atproto.sync.subscribeRepos#info). Carries no seq and does not advance the cursor. OutdatedCursor is sent as the first frame when a unix-microseconds timestamp cursor below the retention floor was clamped up to the floor; the message names the seq actually resumed from.\",\"required\":[\"name\"],\"properties\":{\"name\":{\"type\":\"string\",\"knownValues\":[\"OutdatedCursor\"]},\"message\":{\"type\":\"string\"}}}}}")
        documents.append("{\"defs\":{\"contributor\":{\"properties\":{\"did\":{\"format\":\"did\",\"type\":\"string\"},\"displayName\":{\"maxGraphemes\":100,\"maxLength\":1000,\"type\":\"string\"},\"role\":{\"maxGraphemes\":100,\"maxLength\":1000,\"type\":\"string\"}},\"required\":[\"did\"],\"type\":\"object\"},\"main\":{\"description\":\"A document record representing a published article, blog post, or other content. Documents can belong to a publication or exist independently.\",\"key\":\"tid\",\"record\":{\"properties\":{\"bskyPostRef\":{\"description\":\"Strong reference to a Bluesky post. Useful to keep track of comments off-platform.\",\"ref\":\"com.atproto.repo.strongRef\",\"type\":\"ref\"},\"content\":{\"closed\":false,\"description\":\"Open union used to define the record's content. Each entry must specify a $type and may be extended with other lexicons to support additional content formats.\",\"refs\":[],\"type\":\"union\"},\"contributors\":{\"items\":{\"ref\":\"#contributor\",\"type\":\"ref\"},\"type\":\"array\"},\"coverImage\":{\"accept\":[\"image/*\"],\"description\":\"Image to used for thumbnail or cover image. Less than 1MB is size.\",\"maxSize\":1000000,\"type\":\"blob\"},\"description\":{\"description\":\"A brief description or excerpt from the document.\",\"maxGraphemes\":3000,\"maxLength\":30000,\"type\":\"string\"},\"labels\":{\"description\":\"Self-label values for this post. Effectively content warnings.\",\"refs\":[\"com.atproto.label.defs#selfLabels\"],\"type\":\"union\"},\"links\":{\"description\":\"Array of values describing relationships between this document and external resources\",\"refs\":[],\"type\":\"union\"},\"path\":{\"description\":\"Combine with site or publication url to construct a canonical URL to the document. Prepend with a leading slash.\",\"type\":\"string\"},\"publishedAt\":{\"description\":\"Timestamp of the documents publish time.\",\"format\":\"datetime\",\"type\":\"string\"},\"site\":{\"description\":\"Points to a publication record (at://) or a publication url (https://) for loose documents. Avoid trailing slashes.\",\"format\":\"uri\",\"type\":\"string\"},\"tags\":{\"description\":\"Array of strings used to tag or categorize the document. Avoid prepending tags with hashtags.\",\"items\":{\"maxGraphemes\":128,\"maxLength\":1280,\"type\":\"string\"},\"type\":\"array\"},\"textContent\":{\"description\":\"Plaintext representation of the documents contents. Should not contain markdown or other formatting.\",\"type\":\"string\"},\"title\":{\"description\":\"Title of the document.\",\"maxGraphemes\":500,\"maxLength\":5000,\"type\":\"string\"},\"updatedAt\":{\"description\":\"Timestamp of the documents last edit.\",\"format\":\"datetime\",\"type\":\"string\"}},\"required\":[\"site\",\"title\",\"publishedAt\"],\"type\":\"object\"},\"type\":\"record\"}},\"id\":\"site.standard.document\",\"lexicon\":1}")
        documents.append("{\"defs\":{\"main\":{\"description\":\"Record declaring a recommendation of a document.\",\"key\":\"tid\",\"record\":{\"properties\":{\"createdAt\":{\"format\":\"datetime\",\"type\":\"string\"},\"document\":{\"description\":\"AT-URI reference to the document record being recommended (ex: at://did:plc:abc123/site.standard.document/xyz789).\",\"format\":\"at-uri\",\"type\":\"string\"}},\"required\":[\"document\",\"createdAt\"],\"type\":\"object\"},\"type\":\"record\"}},\"id\":\"site.standard.graph.recommend\",\"lexicon\":1}")
        documents.append("{\"defs\":{\"main\":{\"description\":\"Record declaring a subscription to a publication.\",\"key\":\"tid\",\"record\":{\"properties\":{\"createdAt\":{\"format\":\"datetime\",\"type\":\"string\"},\"publication\":{\"description\":\"AT-URI reference to the publication record being subscribed to (ex: at://did:plc:abc123/site.standard.publication/xyz789).\",\"format\":\"at-uri\",\"type\":\"string\"}},\"required\":[\"publication\"],\"type\":\"object\"},\"type\":\"record\"}},\"id\":\"site.standard.graph.subscription\",\"lexicon\":1}")
        documents.append("{\"defs\":{\"main\":{\"description\":\"A publication record representing a blog, website, or content platform. Publications serve as containers for documents and define the overall branding and settings.\",\"key\":\"tid\",\"record\":{\"properties\":{\"basicTheme\":{\"description\":\"Simplified publication theme for tools and apps to utilize when displaying content.\",\"ref\":\"site.standard.theme.basic\",\"type\":\"ref\"},\"description\":{\"description\":\"Brief description of the publication.\",\"maxGraphemes\":3000,\"maxLength\":30000,\"type\":\"string\"},\"icon\":{\"accept\":[\"image/*\"],\"description\":\"Square image to identify the publication. Should be at least 256x256.\",\"maxSize\":1000000,\"type\":\"blob\"},\"labels\":{\"description\":\"Self-label values for this publication. Effectively content warnings.\",\"refs\":[\"com.atproto.label.defs#selfLabels\"],\"type\":\"union\"},\"name\":{\"description\":\"Name of the publication.\",\"maxGraphemes\":500,\"maxLength\":5000,\"type\":\"string\"},\"preferences\":{\"description\":\"Object containing platform specific preferences (with a few shared properties).\",\"ref\":\"#preferences\",\"type\":\"ref\"},\"url\":{\"description\":\"Base publication url (ex: https://standard.site). The canonical document URL is formed by combining this value with the document path.\",\"format\":\"uri\",\"type\":\"string\"}},\"required\":[\"url\",\"name\"],\"type\":\"object\"},\"type\":\"record\"},\"preferences\":{\"properties\":{\"showInDiscover\":{\"default\":true,\"description\":\"Boolean which decides whether the publication should appear in discovery feeds.\",\"type\":\"boolean\"}},\"type\":\"object\"}},\"id\":\"site.standard.publication\",\"lexicon\":1}")
        documents.append("{\"defs\":{\"main\":{\"description\":\"A simplified theme definition for publications, providing basic color customization for content display across different platforms and applications.\",\"key\":\"tid\",\"record\":{\"properties\":{\"accent\":{\"description\":\"Color used for links and button backgrounds.\",\"refs\":[\"site.standard.theme.color#rgb\"],\"type\":\"union\"},\"accentForeground\":{\"description\":\"Color used for button text.\",\"refs\":[\"site.standard.theme.color#rgb\"],\"type\":\"union\"},\"background\":{\"description\":\"Color used for content background.\",\"refs\":[\"site.standard.theme.color#rgb\"],\"type\":\"union\"},\"foreground\":{\"description\":\"Color used for content text.\",\"refs\":[\"site.standard.theme.color#rgb\"],\"type\":\"union\"}},\"required\":[\"background\",\"foreground\",\"accent\",\"accentForeground\"],\"type\":\"object\"},\"type\":\"record\"}},\"id\":\"site.standard.theme.basic\",\"lexicon\":1}")
        documents.append("{\"defs\":{\"rgb\":{\"properties\":{\"b\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"},\"g\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"},\"r\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"r\",\"g\",\"b\"],\"type\":\"object\"},\"rgba\":{\"properties\":{\"a\":{\"maximum\":100,\"minimum\":0,\"type\":\"integer\"},\"b\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"},\"g\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"},\"r\":{\"maximum\":255,\"minimum\":0,\"type\":\"integer\"}},\"required\":[\"r\",\"g\",\"b\",\"a\"],\"type\":\"object\"}},\"id\":\"site.standard.theme.color\",\"lexicon\":1}")
